201	    @Test
202	    void returnAndNewBorrowResolveByCommitOrderWithoutInconsistentState() throws Exception {
203	        evidenceClock.setClock(Clock.fixed(BASE, ZoneOffset.UTC));
204	        String evidenceKey = uniqueKey("EV");
205	        String firstLoanKey = uniqueKey("LOAN");
206	        String secondLoanKey = uniqueKey("LOAN");
207	        intake("alice", evidenceKey);
208	        ResponseEntity<String> borrowed = controller.borrow("alice", evidenceKey,
209	                new LoanCreateRequest(uniqueKey("CMD"), firstLoanKey, "bob", "鉴定用", due(3600)));
210	        assertThat(borrowed.getStatusCode().value()).isEqualTo(200);
211	
212	        // 归还与再次借出并发（不同 commandKey，均为合法命令），按事务提交顺序处理：
213	        // 归还先提交 → 新借出看到 SEALED 成功；新借出先拿到锁 → 看到 BORROWED 返回 409。
214	        List<Integer> statuses = runConcurrently(
215	                returns("alice", evidenceKey, firstLoanKey, true),
216	                borrow("alice", evidenceKey, secondLoanKey, "carol"));
217	
218	        assertThat(statuses).allMatch(s -> s == 200 || s == 409);
219	        long successCount = statuses.stream().filter(s -> s == 200).count();
220	
221	        var chain = evidenceService.custodyChain(evidenceKey);
222	        if (successCount == 2) {
223	            // 归还先提交：旧借出 RETURNED + 新借出 ACTIVE，证物仍在外借，无丢记录
224	            assertThat(chain.evidence().status()).isEqualTo(EvidenceStatus.BORROWED);
225	            assertThat(chain.loans()).hasSize(2);
