234	            assertThat(chain.evidence().custodianId()).isEqualTo("alice");
235	            assertThat(chain.loans()).hasSize(1);
236	            assertThat(chain.loans().get(0).status()).isEqualTo(LoanStatus.RETURNED);
237	            assertThat(chain.inspections()).hasSize(1);
238	        }
239	        // 任何顺序下都不允许出现归还记录成功而证物仍为 BORROWED 却无 ACTIVE 借出的错配
240	        boolean activeLoan = chain.loans().stream()
241	                .anyMatch(loan -> loan.status() == LoanStatus.ACTIVE);
242	        if (chain.evidence().status() == EvidenceStatus.BORROWED) {
243	            assertThat(activeLoan).isTrue();
244	        } else {
245	            assertThat(activeLoan).isFalse();
246	        }
247	    }
