package com.example.starter.evidence.dto;

import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;

/**
 * 剂量上限登记请求。仅当前保管人可为 SEALED 证物首次登记，登记后不可变。
 * 幂等身份由操作、操作者、证物与全部参数（含期望版本）结构化指纹构成。
 *
 * @param requestId       幂等请求键，全局唯一；同键同参重放返回首次结果，同键改参返回 409
 * @param limitLuxMinutes 剂量上限，单位勒克斯分钟，正值最多3位小数
 * @param expectedVersion 期望账本版本：可选；登记前账本不存在（版本 0），提供时必须为 0，否则 409
 */
public record DoseLimitRegisterRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotNull @Positive @Digits(integer = 15, fraction = 3) BigDecimal limitLuxMinutes,
        Long expectedVersion) {
}

package com.example.starter.evidence.dto;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotNull;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 归还时上报的一段光照区间（UTC，左闭右开）。一次归还须包含 1 至 20 段，
 * 自首段等于实际借出时刻起首尾相接、互不重叠，完整覆盖至归还时刻。
 *
 * @param startAt 段开始时刻（UTC，含）
 * @param endAt   段结束时刻（UTC，不含），须晚于开始时刻
 * @param lux     照度，单位勒克斯，非负最多3位小数
 */
public record DoseSegmentRequest(
        @NotNull LocalDateTime startAt,
        @NotNull LocalDateTime endAt,
        @NotNull @DecimalMin("0") @Digits(integer = 9, fraction = 3) BigDecimal lux) {
}

package com.example.starter.evidence.dto;

import com.example.starter.evidence.DoseStatus;

import java.math.BigDecimal;
import java.util.List;

/**
 * 剂量账本视图。仅当前保管人可查；累计与当次剂量为展示值
 * （勒克斯分钟，HALF_UP 四位），超限判定使用内部精确值，不以展示值为准。
 *
 * @param evidenceKey          关联证物业务键
 * @param limitLuxMinutes      不可变剂量上限（勒克斯分钟）
 * @param cumulativeLuxMinutes 累计剂量展示值（勒克斯分钟，HALF_UP 四位）
 * @param status               账本状态：OK / DOSE_BLOCKED（累计达到或超过上限）
 * @param version              账本版本：登记为1，每次剂量归还递增
 * @param returns              历史剂量归还记录（按发生顺序，冻结不可变）
 */
public record DoseLedgerView(
        String evidenceKey,
        BigDecimal limitLuxMinutes,
        BigDecimal cumulativeLuxMinutes,
        DoseStatus status,
        long version,
        List<DoseReturnView> returns) {
}

package com.example.starter.evidence.dto;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;

/**
 * 一次剂量归还的冻结视图。
 *
 * @param loanKey              对应借出业务键
 * @param returnedAt           实际归还时刻（UTC），即最后一段区间结束时刻
 * @param doseLuxMinutes       当次归还剂量展示值（勒克斯分钟，HALF_UP 四位）
 * @param cumulativeLuxMinutes 本次归还后的累计剂量展示值（勒克斯分钟，HALF_UP 四位）
 * @param segments             本次归还上报的光照区间（按时间顺序，冻结不可变）
 */
public record DoseReturnView(
        String loanKey,
        LocalDateTime returnedAt,
        BigDecimal doseLuxMinutes,
        BigDecimal cumulativeLuxMinutes,
        List<DoseSegmentView> segments) {
}

package com.example.starter.evidence.dto;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 一段冻结的光照区间视图。
 *
 * @param seq            段序号，从1开始
 * @param startAt        段开始时刻（UTC，含）
 * @param endAt          段结束时刻（UTC，不含）
 * @param lux            照度（勒克斯，非负最多3位小数）
 * @param doseLuxMinutes 本段剂量展示值（勒克斯分钟，HALF_UP 四位）
 */
public record DoseSegmentView(
        int seq,
        LocalDateTime startAt,
        LocalDateTime endAt,
        BigDecimal lux,
        BigDecimal doseLuxMinutes) {
}

