    assertThat(ledger.get("status").asText()).isEqualTo("OK");
    assertThat(ledger.get("version").asLong()).isEqualTo(1);

    String loan1 = uniqueKey("LOAN");
    assertThat(borrow("alice", evidenceKey, loan1, "bob", utc(BASE.plusSeconds(3600)))
