private Callable<ResponseEntity<String>> guarding(Callable<ResponseEntity<String>> call) {
    return () -> {
        try {
            return call.call();
        } catch (ApiException e) {
            return ResponseEntity.status(e.status()).body(e.getMessage());
        }
    };
}
