        assertThat(segments).hasSize(3);
        assertThat(segments.get(0).get("doseLuxMinutes").asText()).isEqualTo("5.0000");
        assertThat(segments.get(1).get("doseLuxMinutes").asText()).isEqualTo("3.0000");
        assertThat(segments.get(2).get("doseLuxMinutes").asText()).isEqualTo("0.2500");

