    @Test
    void custodyTransferKeepsLedgerAndNewCustodianInheritsBlock() throws Exception {
        String evidenceKey = uniqueKey("EV");
        intake("alice", evidenceKey);
        fixClock(BASE);
        registerLimit("alice", evidenceKey, "5");
        String loanKey = uniqueKey("LOAN");
